package io.github.jesterportfolio.hearth.combat;

import io.github.jesterportfolio.hearth.persistence.ServerProgressAccess;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;
import static io.github.jesterportfolio.hearth.combat.FieldEncounters.*;

final class FieldCombatTest {
    static final class F {
        final UUID run=UUID.randomUUID(),world=UUID.randomUUID();final Binding binding=new Binding(run,world,1);final ServerProgressAccess access=new ServerProgressAccess();final AtomicLong time=new AtomicLong(10),generation=new AtomicLong(1);
        final Queue<Runnable> jobs=new ArrayDeque<>();final java.util.concurrent.Executor owner=jobs::add;
        final FieldContent.Zone zone=FieldEncountersTest.zone("first",0);
        final Exit exit=new Exit(new FieldContent.Point(7,64,8),12,13,.5,List.of());
        final CombatContent dungeon=new CombatContent("dungeon","공개 인던",20,2,3000,CombatAttemptTest.content(Pool.SHARED,1,LocationMode.START).revival(),new Retry("BOSS_ONLY",new FieldContent.Point(3,64,4),0,0,1,List.of()),exit);
        final CombatContent content=FieldCombat.definition(zone,dungeon);
        final CombatPlayersTest.Body p=new CombatPlayersTest.Body(access.forVerifiedServerLink(run,UUID.randomUUID()),new Pose(world,1,64,1,0,0)),q=new CombatPlayersTest.Body(access.forVerifiedServerLink(run,UUID.randomUUID()),new Pose(world,2,64,1,0,0));
        final CombatPlayers bridge=new CombatPlayers(run,world,1,generation::get,owner,()->{});
        final CombatAttempt battle=new CombatAttempt(run,world,1,content,List.of(new CombatAttempt.Entrant(p.ctx,p.token,p.position),new CombatAttempt.Entrant(q.ctx,q.token,q.position)),bridge,owner,()->{},time::get);
        F(){bridge.attach(battle,List.of(p,q));}void pump(){while(!jobs.isEmpty())jobs.remove().run();}
    }
    @Test void sameDungeonRevivalExitAndProtectionWithoutBossRestartPathOrPattern(){var f=new F();assertSame(f.dungeon.revival(),f.content.revival());assertSame(f.exit,f.content.exit());assertEquals(3000,f.content.returnProtectionMillis());assertEquals(f.zone.title(),f.content.title());assertNull(f.content.path());assertNull(f.content.retry());assertTrue(f.content.patterns().isEmpty());assertThrows(IllegalStateException.class,()->FieldCombat.definition(f.zone,CombatAttemptTest.content(Pool.SHARED,1,LocationMode.START)));}
    @Test void rosterUsesOnlyMatchingProgressGenerationAndSelectedPopulationWithoutDuplicates(){var f=new F();var c=new FieldContent(List.of(f.zone,FieldEncountersTest.zone("next",10)));var one=new Presence(f.binding,f.p.ctx.playerId(),new FieldContent.Point(1,64,1));var inputs=List.of(one,one,new Presence(f.binding,f.q.ctx.playerId(),new FieldContent.Point(100,64,100)),new Presence(new Binding(UUID.randomUUID(),f.world,1),UUID.randomUUID(),one.location()),new Presence(new Binding(f.run,f.world,2),UUID.randomUUID(),one.location()));assertEquals(Set.of(f.p.ctx.playerId()),FieldCombat.roster(c,f.binding,List.of("first"),inputs));assertThrows(IllegalStateException.class,()->FieldCombat.roster(c,f.binding,List.of("next"),inputs));assertThrows(IllegalArgumentException.class,()->FieldCombat.roster(c,f.binding,List.of("missing"),inputs));assertThrows(IllegalArgumentException.class,()->FieldCombat.roster(c,f.binding,List.of("first","first"),inputs));}
    @Test void existingDungeonOrFieldAttemptCannotAddLateMemberOrDifferentScope(){var f=new F();assertTrue(FieldCombat.joinable(f.battle,f.binding,Set.of(f.p.ctx.playerId())));assertFalse(FieldCombat.joinable(f.battle,f.binding,Set.of(UUID.randomUUID())));assertFalse(FieldCombat.joinable(f.battle,new Binding(f.run,UUID.randomUUID(),1),Set.of(f.p.ctx.playerId())));assertFalse(FieldCombat.joinable(f.battle,new Binding(f.run,f.world,2),Set.of(f.p.ctx.playerId())));f.battle.victory();assertFalse(FieldCombat.joinable(f.battle,f.binding,Set.of(f.p.ctx.playerId())));}
    @Test void deathSpectatorConditionAndSharedRevivalBudgetUseOriginalController(){var f=new F();var inventory=f.p.inventory.clone();f.bridge.died(f.p);f.bridge.project();assertTrue(f.p.spectator);assertEquals(f.q.ctx.playerId(),f.p.target);assertFalse(f.bridge.actions(f.p));assertTrue(f.bridge.actions(f.q));assertThrows(CompletionException.class,()->f.battle.revive(f.p.ctx,f.p.token,UUID.randomUUID(),"wrong").toCompletableFuture().join());var request=UUID.randomUUID();var revived=f.battle.revive(f.p.ctx,f.p.token,request,"rescue");assertSame(revived,f.battle.revive(f.p.ctx,f.p.token,request,"rescue"));assertFalse(f.bridge.barrier().toCompletableFuture().isDone());f.p.applying.complete(true);f.pump();assertFalse(revived.toCompletableFuture().isCompletedExceptionally());assertEquals(1,f.battle.snapshot().sharedUsed());assertTrue(f.bridge.actions(f.p));assertArrayEquals(inventory,f.p.inventory);f.bridge.died(f.q);assertTrue(f.battle.revive(f.q.ctx,f.q.token,UUID.randomUUID(),"rescue").toCompletableFuture().isCompletedExceptionally());}
    @Test void deathReconnectionKeepsFixedRosterAndExactPose(){var f=new F();f.bridge.died(f.p);f.bridge.leave(f.p);var next=new CombatPlayersTest.Body(f.p.ctx,f.bridge.returnPosition(f.p.ctx).orElseThrow());f.bridge.rejoin(next);f.bridge.project();assertTrue(next.spectator);assertEquals(2,f.battle.snapshot().difficultyPlayers());assertFalse(f.bridge.actions(next));assertFalse(f.bridge.current(f.p));assertTrue(FieldCombat.joinable(f.battle,f.binding,Set.of(f.q.ctx.playerId())));}
    @Test void wipeWaitHasNoAutomaticResetAndExplicitFailureCanUseSavedReturn(){var f=new F();f.bridge.died(f.p);f.bridge.died(f.q);f.bridge.project();assertEquals(CombatAttempt.Phase.WIPE_WAIT,f.battle.snapshot().phase());assertFalse(CombatReturn.ended(f.battle.snapshot()));f.battle.failedCondition(true);assertTrue(CombatReturn.ended(f.battle.snapshot()));var saved=new CompletableFuture<Void>();var returned=new CombatReturn(f.battle,f.exit,f.p,()->saved,()->f.bridge.leave(f.p),f.owner,()->{},()->true);var result=returned.begin();f.pump();assertEquals(0,f.p.restores);saved.complete(null);f.pump();assertEquals(1,f.p.restores);f.p.applying.complete(true);f.pump();assertFalse(result.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatReturn.Phase.DONE,returned.phase());assertEquals(f.exit.pose(f.world),f.p.position);assertTrue(f.p.cleanup);}
    @Test void returnFailureAndGenerationChangeKeepInventoryAndNoSuccess(){var f=new F();f.battle.victory();var before=f.p.inventory.clone();var returned=new CombatReturn(f.battle,f.exit,f.p,()->CompletableFuture.failedFuture(new IllegalStateException("DB_FAILED")),()->fail("cleanup"),f.owner,()->{},()->true);returned.begin();f.pump();assertEquals(CombatReturn.Phase.HOLD,returned.phase());assertEquals(0,f.p.restores);assertArrayEquals(before,f.p.inventory);var other=new F();other.bridge.died(other.p);var revive=other.battle.revive(other.p.ctx,other.p.token,UUID.randomUUID(),"rescue");other.generation.incrementAndGet();other.bridge.project();other.p.applying.complete(true);other.pump();assertTrue(revive.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatAttempt.Phase.HOLD,other.battle.snapshot().phase());}
    @Test void victoryRequiresAllSelectedManagedZonesCleared(){var f=new FieldEncountersTest.Fixture();f.enter();f.engine.enter(f.a,f.p,new FieldContent.Point(-2,64,0),new FieldContent.Point(11,64,1),f.players(f.a,new FieldContent.Point(11,64,1)));assertFalse(FieldCombat.cleared(f.engine,f.a,Set.of("first","next")));for(UUID id:f.first().mobs())f.engine.died(f.a,"first",id);assertFalse(FieldCombat.cleared(f.engine,f.a,Set.of("first","next")));for(UUID id:f.engine.state(f.a.run(),"next").orElseThrow().mobs())f.engine.died(f.a,"next",id);assertTrue(FieldCombat.cleared(f.engine,f.a,Set.of("first","next")));f.engine.retire(f.a.run());assertThrows(IllegalStateException.class,()->FieldCombat.cleared(f.engine,f.a,Set.of("first")));}
    @Test void settledUnfinishedZoneKeepsOtherProgressAndNeedsExplicitReset(){var f=new FieldEncountersTest.Fixture();f.enter();f.engine.enter(f.b,f.p,new FieldContent.Point(-2,64,0),new FieldContent.Point(1,64,1),f.players(f.b,new FieldContent.Point(1,64,1)));var other=f.engine.state(f.b.run(),"first");f.engine.settle(f.a,Set.of("first"));assertEquals(Phase.RETIRED,f.first().phase());assertEquals(other,f.engine.state(f.b.run(),"first"));assertEquals(2,f.live.size());f.enter();assertEquals(Phase.RETIRED,f.first().phase());assertThrows(IllegalStateException.class,()->FieldCombat.cleared(f.engine,f.a,Set.of("first")));f.engine.reset(f.a,UUID.randomUUID(),new FieldReset(FieldReset.Mode.ALL,List.of("first"),null));f.enter();assertEquals(Phase.ACTIVE,f.first().phase());assertEquals(2,f.first().players());}
    @Test void settleFailurePreservesRemainingManagedEntitiesInHold(){var f=new FieldEncountersTest.Fixture();f.enter();var ids=f.first().mobs();f.removeFails=true;assertThrows(IllegalStateException.class,()->f.engine.settle(f.a,Set.of("first")));assertEquals(Phase.ERROR_HOLD,f.first().phase());assertEquals(ids,f.first().mobs());assertEquals(ids,f.live);assertThrows(IllegalStateException.class,()->f.engine.settle(f.a,Set.of("first")));}
}
